#include <cassert>

#include "phase4_judge_test_support.hpp"

int main(){using namespace phase4_judge_test;auto s=suite("task-f6e-workflow");DatasetRegistry data;populate(data,s);auto b=run(s,false),c=run(s,true);memory_v2::MemoryProviderRegistry providers;memory_v2::MemoryViewEngine views(providers);InMemoryJudgeStore store;ScriptedJudge model;LLMJudgeWorkflow workflow(views,store,model);auto result=workflow.run(s,data,b,c,subject(s.metadata),options());assert(result.state==JudgeWorkflowState::Approved);assert(result.report&&result.report->executed);assert(result.report->decision.rollback_revision=="baseline-r1");assert(result.report->calibration.raw_agreement==1.0);assert(result.report->calibration.ground_truth_accuracy==1.0);assert(result.report->metrics.comparisons.size()==metric_names().size());assert(result.report->metrics.missing_metrics.empty());assert(result.report->metrics.critical_violations.empty());assert(decode_evaluation_report(encode(*result.report)));assert(model.requests.size()==2);for(const auto&r:model.requests){assert(r.memory_view.manifest.view_digest==result.checkpoint.memory_view_digest);auto text=r.input.dump();assert(text.find("candidate-r2")==std::string::npos);assert(text.find("baseline-r1")==std::string::npos);assert(text.find("provider-")==std::string::npos);assert(text.find("ground_truth")==std::string::npos);assert(r.input.at("suite_alias")=="blind-suite");}auto again=workflow.run(s,data,b,c,subject(s.metadata),options());assert(again.state==JudgeWorkflowState::Approved&&model.requests.size()==2);
    auto disputed_suite=suite("task-f6e-adjudication");DatasetRegistry disputed_data;populate(disputed_data,disputed_suite);auto db=run(disputed_suite,false),dc=run(disputed_suite,true);InMemoryJudgeStore disputed_store;ScriptedJudge disputed_model;disputed_model.secondary_disagrees=true;LLMJudgeWorkflow disputed_workflow(views,disputed_store,disputed_model);auto disputed=disputed_workflow.run(disputed_suite,disputed_data,db,dc,subject(disputed_suite.metadata),options("adjudication-f6e"));assert(disputed.state==JudgeWorkflowState::ManualReview&&disputed.report&&disputed.report->adjudication);assert(disputed.report->calibration.disputed_case_ids.size()==2&&disputed_model.requests.size()==3);return 0;}
